"""Pin one public Japanese source generated by a32B teacher, without inference."""
import dataclasses
import json
import os
from pathlib import Path
import sys
os.environ['HF_HUB_DISABLE_IMPLICIT_TOKEN']='1'
sys.path.insert(0,str(Path(__file__).resolve().parents[1]/'src'))
from huggingface_hub import HfApi
from jmicro.experiment import ROOT,now,write_json


def main():
    target=ROOT/'reports/phase6/public_magpie_source_metadata.json'
    if target.exists():raise ValueError('Preserve pinned metadata')
    info=HfApi(token=False).dataset_info('llm-jp/magpie-sft-v1.0',files_metadata=True,token=False)
    files=[]
    for e in info.siblings:
        if e.rfilename in ('README.md','magpie-sft-v1.0.jsonl','LICENSE'):
            lfs=dataclasses.asdict(e.lfs) if dataclasses.is_dataclass(e.lfs) else e.lfs
            files.append(dict(path=e.rfilename,bytes=e.size,blob_id=e.blob_id,lfs=lfs))
    license=info.card_data.to_dict().get('license')
    if info.gated or info.private or license!='apache-2.0':raise ValueError('Public Apache2 dataset required')
    result=dict(status='public_anonymous_pinned_Magpie_metadata_not_recovered',repo_id=info.id,revision=info.sha,
        gated=info.gated,private=info.private,license=license,files=files,total_bytes=sum(f['bytes'] or 0 for f in files),
        created_at=now(),anonymous_access=True,source_url='https://huggingface.co/datasets/llm-jp/magpie-sft-v1.0',
        role='Candidate standalone assistant-authored prose bodies for Base fullbody+EOS CE only; no User/Assistant role tokens, EOT, conversation or SFT training.',
        prior_generated_teacher_source_rejected='public_prose_teacher_content_review.json: weak37/64; no local teacher retry',
        student_scientific_teacher_tokens=0,Chat_started=False,quantization_started=False)
    write_json(target,result);print(json.dumps({k:result[k] for k in ('status','repo_id','revision','license','total_bytes')}))


if __name__=='__main__':
    if sys.version_info[:3]!=(3,12,7):raise RuntimeError('Pinned uv Python required')
    main()
